from __future__ import annotations

import asyncio
import sys
from pathlib import Path
from typing import Any

import pytest
from pydantic_ai.messages import ModelMessage, ModelRequest, ModelResponse, TextPart, ToolCallPart, UserPromptPart
from pydantic_ai.models.function import AgentInfo, FunctionModel

# the app has no package install: import it from its folder
APP_DIR = Path(__file__).resolve().parents[3] / "services" / "ui"
sys.path.insert(0, str(APP_DIR))

import ds.ai  # noqa: E402
from ui import inline, inline_fill  # noqa: E402
from ui.render import Ui, apply_event, to_view  # noqa: E402
from ui.session import Session  # noqa: E402
from ui.tool_forms import ToolRequest  # noqa: E402
from ui.widgets import TOOL_FORMS, form_by_key  # noqa: E402

FORMS = pytest.mark.parametrize("form", TOOL_FORMS, ids=lambda form: form.key)
USAGE = form_by_key("get_player_usage")
GOOD = {"player": "Sparg0", "vs_characters": ["steve"], "setting": "offline", "sets": 90}


def answering(answers: list[dict[str, Any]], calls: list[tuple[list[ModelMessage], AgentInfo]]) -> FunctionModel:
    """A stand-in model that proposes each of `answers` in turn (the last one again after that)
    and records what each request sent.
    """

    def respond(messages: list[ModelMessage], info: AgentInfo) -> ModelResponse:
        calls.append((list(messages), info))
        answer = answers[min(len(calls), len(answers)) - 1]
        return ModelResponse(parts=[ToolCallPart(info.output_tools[0].name, answer)])

    return FunctionModel(respond)


def ask(form: Any, answers: list[dict[str, Any]], shown: dict[str, Any] | None = None, session: Any = None) -> tuple:
    calls: list[tuple[list[ModelMessage], AgentInfo]] = []
    with ds.ai.agent.override(model=answering(answers, calls)):
        answer = asyncio.run(inline_fill.fill(session, form, shown or {}, "sparg0 vs steve offline, 90 sets"))
    return answer, calls


@FORMS
def test_the_answer_has_the_forms_inputs_and_nothing_hidden(form):
    """The AI answers in the tool's own parameter schema, minus what the form hides."""
    properties = form.fill_schema["properties"]
    assert list(properties) == [field.name for field in form.fields({})]
    assert not set(form.hide) & set(properties)
    assert set(form.fill_schema["required"]) <= set(properties)
    # what the model is really given as its answer's shape
    _, calls = ask(form, [{}])
    assert list(calls[0][1].output_tools[0].parameters_json_schema["properties"]) == list(properties)


def test_a_proposal_comes_back_as_the_forms_text():
    answer, calls = ask(USAGE, [GOOD])
    assert answer.error == ""
    assert answer.inputs == {"player": "Sparg0", "vs_characters": "steve", "setting": "offline", "sets": "90"}
    assert answer.usage.endswith("1 request")
    assert len(calls) == 1


def test_the_prompt_has_the_tool_and_what_the_form_shows_now():
    text = inline_fill.prompt(USAGE, USAGE.texts({"player": "MkLeo"}), "offline only", note="MkLeo · 30 sets")
    assert "Player usage (get_player_usage)" in text
    assert "Get which characters and stages a player picks" in text  # the tool's own description
    # what each input means travels in the answer's schema, as it does for the chat agent
    assert "only count games against" in USAGE.fill_schema["properties"]["vs_characters"]["description"]
    assert '"player": "MkLeo"' in text
    assert '"sets": "30"' in text  # an input left alone shows its default
    assert "MkLeo · 30 sets" in text
    assert text.endswith("Instruction: offline only")


def test_what_is_typed_but_not_run_is_what_the_ai_changes():
    _, calls = ask(USAGE, [GOOD], shown={"player": "MkLeo", "sets": "60"})
    sent = str(calls[0][0][-1].parts[-1].content)
    assert '"player": "MkLeo"' in sent
    assert '"sets": "60"' in sent


def test_a_bad_answer_goes_back_to_the_model_with_the_validators_words():
    answer, calls = ask(USAGE, [GOOD | {"setting": "bogus"}, GOOD])
    assert answer.error == ""
    assert answer.inputs["setting"] == "offline"
    assert answer.fixes == 1
    assert answer.usage.endswith("2 requests")
    assert "setting" in str(calls[1][0][-1].parts[-1].content)


def test_an_answer_that_never_validates_fails_instead_of_filling_the_form():
    answer, calls = ask(USAGE, [GOOD | {"sets": 31}])
    assert answer.inputs == {}
    assert "don't pass Player usage's check" in answer.error
    assert len(calls) == inline.MAX_FIXES + 1


def test_it_needs_an_instruction():
    answer = asyncio.run(inline_fill.fill(None, USAGE, {}, "   "))
    assert answer.error
    assert answer.usage == ""


def test_the_chat_goes_along_and_the_turn_joins_it():
    history = [ModelRequest(parts=[UserPromptPart("who won Kagaribi?")]), ModelResponse(parts=[TextPart("acola")])]
    session = Session()
    session.ai_history = list(history)
    _, calls = ask(USAGE, [GOOD], session=session)
    assert calls[0][0][: len(history)] == history
    # a turn of the chat: its messages come after the chat's own
    assert session.ai_history[: len(history)] == history
    assert len(session.ai_history) > len(history)
    # the stand-in model has no price: the session's total stays (unpriced requests don't add)
    assert session.ai_cost == 0.0


def test_the_agent_has_no_tools():
    """It fills inputs; it can't run the tool or look anything up."""
    _, calls = ask(USAGE, [GOOD])
    assert calls[0][1].function_tools == []


def test_a_proposal_is_shown_in_the_form_with_its_changes_marked():
    view = to_view(ToolRequest(USAGE.key, {"player": "MkLeo"}))
    ui = Ui(proposed={"player": "MkLeo", "vs_characters": "steve", "setting": "offline", "sets": "30"})
    data = view.data("tab:r1", ui)
    fields = {field.name: field for field in data.form}
    assert data.ai_proposed
    assert fields["setting"].value == "offline"
    assert [name for name, field in fields.items() if field.changed] == ["vs_characters", "setting"]
    assert fields["setting"].help.startswith("Was: all.")
    assert fields["vs_characters"].help.startswith("Was: (empty).")
    # without a proposal: the inputs that made the value, nothing marked
    plain = view.data("tab:r1", Ui())
    assert not plain.ai_proposed
    assert not any(field.changed for field in plain.form)


def test_a_proposal_remounts_the_form_and_closing_puts_the_inputs_back():
    view = to_view(ToolRequest(USAGE.key))
    ui = Ui()
    apply_event(view, ui, "ai_toggle", "")
    assert ui.ai_open
    assert ui.form_open  # the Ask AI box belongs to the form
    before = view.data("tab:r1", ui).form_key
    ui.proposed, ui.proposals = {"player": "Sparg0"}, ui.proposals + 1
    shown = view.data("tab:r1", ui).form_key
    assert shown != before  # the inputs are uncontrolled: only a remount shows new values
    apply_event(view, ui, "ai_discard", "")
    assert ui.proposed == {}
    assert not ui.ai_open
    assert view.data("tab:r1", ui).form_key not in (before, shown)
